def update(self, dt):
    self.pos += self.velocity * dt
    self.rect.center = (round(self.pos.x), round(self.pos.y))

def update(self, dt):
    super().update(dt)
    if self.rect.bottom < PLAY_AREA.top:
        self.kill()

class WeavingEnemy(Enemy):
    def __init__(self, name, position, speed=80, hp=1):
        super().__init__(name, position, speed, hp)
        self.elapsed = 0.0

    def update(self, dt):
        self.elapsed += dt
        self.velocity.x = 100 * cos(3 * self.elapsed)
        super().update(dt)

class Spark:
    def __init__(self) -> None:
        self.ttl = 1.0

    def update(self, dt: float) -> None:
        self.ttl = max(0.0, self.ttl - dt)

class BadClock:
    def update(self):
        pass

bad = BadClock()
bad.update(0.5)  # TypeError

from abc import ABC, abstractmethod

class UpdateableABC(ABC):
    @abstractmethod
    def update(self, dt: float) -> None:
        pass

class FallingTarget(UpdateableABC):
    def __init__(self) -> None:
        self.y = 0.0

    def update(self, dt: float) -> None:
        self.y += 80.0 * dt

from typing import Protocol
from collections.abc import Iterable

class Updatable(Protocol):
    def update(self, dt: float) -> None: ...

def tick_all(items: Iterable[Updatable], dt: float) -> None:
    for item in items:
        item.update(dt)

from typing import Protocol

class Motion(Protocol):
    def velocity(self, dt: float) -> tuple[float, float]: ...

from math import cos

class Straight:
    def velocity(self, dt: float) -> tuple[float, float]:
        return (0.0, 80.0)

class Weave:
    def __init__(self) -> None:
        self.elapsed = 0.0

    def velocity(self, dt: float) -> tuple[float, float]:
        self.elapsed += dt
        return (100.0 * cos(3.0 * self.elapsed), 80.0)

class StrategyEnemy(Enemy):
    def __init__(self, name, position, motion: Motion):
        super().__init__(name, position)
        self.motion = motion

    def update(self, dt):
        vx, vy = self.motion.velocity(dt)
        self.velocity.update(vx, vy)
        super().update(dt)

class Freeze:
    def velocity(self, dt: float) -> tuple[float, float]:
        return (0.0, 0.0)

enemy.motion = Freeze()
before = tuple(enemy.pos)
original = enemy
enemy.update(0.5)
assert tuple(enemy.pos) == before
assert enemy is original

